package dev.gamersclt.batcaverna.nativeapp;
import android.content.Context;
import android.widget.*;
import org.json.*;
/** Shared account progress and full-library statistics from the authenticated RPC. */
final class JourneySheet {
 private final Context c;private final NativeSheet sheet;private final AccountRepository repo;private final String owner;private int generation;private boolean busy;private TextView state;
 private JourneySheet(Context context,String title){c=context;sheet=new NativeSheet(c,title);repo=new AccountRepository(c);owner=c.getSharedPreferences("batcaverna",0).getString("user_id","");sheet.show();}
 static void progress(Context c,String id){new JourneySheet(c,"Progresso de episódios").load(id);}
 static void statistics(Context c){new JourneySheet(c,"Minhas estatísticas").stats();}
 private boolean active(){return sheet.dialog.isShowing()&&owner.equals(c.getSharedPreferences("batcaverna",0).getString("user_id",""));}
 private int reset(String value){generation++;sheet.body.removeAllViews();state=text(value,13);return generation;}
 private TextView text(String value,int size){TextView t=NativeSheet.text(c,value,size,0xffd6c9e6);sheet.body.addView(t);return t;}
 private Button button(String label,Runnable click){Button b=new Button(c);b.setText(label);AppStyle.button(b,false);sheet.body.addView(b,new LinearLayout.LayoutParams(-1,-2));b.setOnClickListener(v->{if(active()&&!busy)click.run();});return b;}
 private JSONObject args(String id,long revision){try{return new JSONObject().put("item_id",id).put("revision",revision);}catch(JSONException e){throw new IllegalArgumentException(e);}}
 private void load(String id){int g=reset("Carregando…");repo.journey("progress",args(id,0),(rows,error)->{if(!active()||g!=generation)return;if(error!=null){state.setText(error);button("Tentar novamente",()->load(id));return;}render(rows.optJSONObject(0));});}
 private EditText number(String label,int current,boolean optional){text(label,14);EditText e=NativeSheet.input(c,label,6);e.setInputType(android.text.InputType.TYPE_CLASS_NUMBER);e.setText(optional&&current==0?"":String.valueOf(current));sheet.body.addView(e);return e;}
 private void render(JSONObject p){if(p==null)return;busy=false;reset("");String id=p.optString("item_id");long revision=p.optLong("revision");int season=p.optInt("temporada",1),episode=p.optInt("episodio"),total=p.optInt("total");text(p.optString("nome"),22);text("Último assistido • temporada "+season+", episódio "+episode+(episode==0?" (nenhum nesta temporada)":""),15);Button next=button("Próximo episódio",()->save("next_episode",args(id,revision),id));next.setEnabled(total<=0||episode<total);button("Próxima temporada",()->save("next_season",args(id,revision),id));button("Atualizar progresso",()->load(id));EditText s=number("Temporada",season,false),ep=number("Último episódio assistido",episode,false),n=number("Total de episódios desta temporada (opcional)",total,true);text("Episódio 0 significa que ainda não começou. A próxima temporada volta ao episódio 0 e deixa o total em branco. O status da biblioteca é editado separadamente.",13);button("Salvar progresso",()->{try{int sv=Integer.parseInt(s.getText().toString()),ev=Integer.parseInt(ep.getText().toString());String nt=n.getText().toString();Integer nv=nt.isEmpty()?null:Integer.valueOf(nt);if(sv<1||sv>10000||ev<0||ev>100000||(nv!=null&&(nv<1||nv>100000||ev>nv)))throw new IllegalArgumentException();JSONObject d=args(id,revision).put("temporada",sv).put("episodio",ev).put("total",nv==null?JSONObject.NULL:nv);save("save_progress",d,id);}catch(Exception e){state.setText("Confira temporada, episódio e total de episódios.");}});text("Progresso salvo na conta, compartilhado entre site e APK.",12);}
 private void save(String action,JSONObject data,String id){if(busy||!active())return;busy=true;sheet.busy(true);int g=generation;state.setText("Salvando…");repo.journey(action,data,(rows,error)->{busy=false;sheet.busy(false);if(!active()||g!=generation)return;if(error!=null){reset(error+" Atualize antes de tentar novamente.");button("Atualizar progresso",()->load(id));return;}render(rows.optJSONObject(0));});}
 private void stats(){int g=reset("Calculando sua biblioteca completa…");repo.journey("stats",new JSONObject(),(rows,error)->{if(!active()||g!=generation)return;if(error!=null){state.setText(error);button("Tentar novamente",this::stats);return;}JSONObject p=rows.optJSONObject(0);if(p==null){state.setText("Não foi possível calcular.");return;}state.setText("");text(p.optInt("total")+" títulos • "+p.optInt("concluidos")+" concluídos",23);text(java.text.NumberFormat.getNumberInstance(new java.util.Locale("pt","BR")).format(p.optDouble("horas"))+" horas jogadas registradas",17);text(p.optInt("jogos")+" jogos • "+p.optInt("filmes")+" filmes\n"+p.optInt("series")+" séries • "+p.optInt("animes")+" animes",15);text("Conclusões por mês",21);text("Últimos 12 meses, pela data de finalização. "+p.optInt("sem_data")+" concluídos sem data ficam fora da evolução mensal.",13);JSONArray months=p.optJSONArray("months");int max=1;if(months!=null){for(int i=0;i<months.length();i++){JSONObject m=months.optJSONObject(i);max=Math.max(max,m.optInt("jogos")+m.optInt("midias"));}for(int i=0;i<months.length();i++){JSONObject m=months.optJSONObject(i);String month=m.optString("mes");int games=m.optInt("jogos"),media=m.optInt("midias");text((month.length()==7?month.substring(5)+"/"+month.substring(0,4):month)+" • "+games+" jogos • "+media+" mídias",13);ProgressBar bar=new ProgressBar(c,null,android.R.attr.progressBarStyleHorizontal);bar.setMax(max);bar.setProgress(games+media);bar.setContentDescription(month+" • "+(games+media)+" concluídos");sheet.body.addView(bar,new LinearLayout.LayoutParams(-1,NativeSheet.dp(c,12)));}}text("Platinados e favoritos contam como concluídos. As horas são o total atual dos jogos, sem estimar horas por mês.",13);button("Atualizar estatísticas",this::stats);});}
}
